package dev.webshield.core;
import java.io.*;import java.nio.file.*;import java.time.Duration;import java.util.Properties;
public record Config(int burstCapacity,double refillPerSecond,int rollingQuota,Duration rollingWindow,Duration cooldown,double surgeMultiplier,double surgeAbsoluteRps,Duration surgeDuration,int violationThreshold,Duration temporaryBlock,Path allowlist,Path blacklist,Path logFile){
 public static Config load(Path p){try{Properties x=new Properties();if(Files.exists(p))try(var in=Files.newInputStream(p)){x.load(in);}return new Config(i(x,"burst.capacity",30),d(x,"burst.refillPerSecond",5),i(x,"quota.limit",500),Duration.ofSeconds(i(x,"quota.windowSeconds",3600)),Duration.ofSeconds(i(x,"quota.cooldownSeconds",600)),d(x,"surge.multiplier",4),d(x,"surge.absoluteRps",100),Duration.ofSeconds(i(x,"surge.durationSeconds",60)),i(x,"violations.beforeBlock",5),Duration.ofSeconds(i(x,"temporaryBlockSeconds",300)),Path.of(x.getProperty("allowlist.file","config/allowlist.txt")),Path.of(x.getProperty("blacklist.file","config/blacklist.txt")),Path.of(x.getProperty("log.file","logs/access.jsonl")));}catch(IOException e){throw new IllegalStateException(e);}}
 private static int i(Properties p,String k,int v){return Integer.parseInt(p.getProperty(k,String.valueOf(v)));}private static double d(Properties p,String k,double v){return Double.parseDouble(p.getProperty(k,String.valueOf(v)));}
}
